import{_ as i,a0 as l,w as p,s as a,I as n,x as e,a1 as s,A as r,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux有问必答：如何在CentOS7上改变网络接口名 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在CentOS7上改变网络接口名 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在CentOS7上改变网络接口名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在CentOS7上改变网络接口名 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140925 Linux FAQs with Answers--How to change a network interface name on CentOS 7","title":"Linux有问必答：如何在CentOS7上改变网络接口名","tag":"201410","desc":""},"relativePath":"201410/20140925 Linux FAQs with Answers--How to change a network interface name on CentOS 7.md","filePath":"[post].md"}'),d={name:"201410/20140925 Linux FAQs with Answers--How to change a network interface name on CentOS 7.md"};function m(f,t,g,C,x,L){const o=l("Link");return p(),a("div",null,[t[14]||(t[14]=n("h1",{id:"linux有问必答-如何在centos7上改变网络接口名",tabindex:"-1"},[e("Linux有问必答：如何在CentOS7上改变网络接口名 "),n("a",{class:"header-anchor",href:"#linux有问必答-如何在centos7上改变网络接口名","aria-label":"Permalink to “Linux有问必答：如何在CentOS7上改变网络接口名”"},"​")],-1)),t[15]||(t[15]=n("blockquote",null,[n("p",null,[n("strong",null,"提问"),e(": 在CentOS7，我想将分配的网络接口名更改为别的名字。有什么合适的方法来来重命名CentOS或RHEL7的网络接口？")])],-1)),t[16]||(t[16]=n("p",null,"传统上，Linux的网络接口被枚举为eth[0123...]，但这些名称并不一定符合实际的硬件插槽，PCI位置，USB接口数量等，这引入了一个不可预知的命名问题（例如，由于不确定的设备探测行为），这可能会导致不同的网络配置错误（例如，由无意的接口改名引起的禁止接口或者防火墙旁路）。基于MAC地址的udev规则在虚拟化的环境中并不有用，这里的MAC地址如端口数量一样无常。",-1)),n("p",null,[t[1]||(t[1]=e("CentOS/RHEL6引入了",-1)),s(o,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/6/html/Deployment_Guide/appe-Consistent_Network_Device_Naming.html"},{default:r(()=>[...t[0]||(t[0]=[e("一致和可预测的网络设备命名",-1)])]),_:1}),t[2]||(t[2]=e("网络接口的方法。这些特性可以唯一地确定网络接口的名称以使定位和区分设备更容易，并且在这样一种方式下，无论是否重启机器、过了多少时间、或者改变硬件，其名字都是持久不变的。然而，这种命名规则并不是默认在CentOS/RHEL6上开启。",-1))]),t[17]||(t[17]=u(`<p>从CentOS/RHEL7起，这种可预见的命名规则变成了默认。根据这一规则，接口名称被自动基于固件，拓扑结构和位置信息来确定。现在，即使添加或移除网络设备，接口名称仍然保持固定，而无需重新枚举，和坏掉的硬件可以无缝替换。</p><pre><code>* 基于接口类型的两个字母前缀:
*   en -- 以太网
*   sl -- 串行线路IP (slip)
*   wl -- wlan
*   ww -- wwan
*
* 名字类型:
*   b&lt;number&gt;                             -- BCMA总线和新书
*   ccw&lt;name&gt;                             -- CCW总线组名
*   o&lt;index&gt;                              -- 车载设备的索引号
*   s&lt;slot&gt;[f&lt;function&gt;][d&lt;dev_port&gt;]     -- 热插拔插槽索引号
*   x&lt;MAC&gt;                                -- MAC 地址
*   [P&lt;domain&gt;]p&lt;bus&gt;s&lt;slot&gt;[f&lt;function&gt;][d&lt;dev_port&gt;]
*                                         -- PCI 位置
*   [P&lt;domain&gt;]p&lt;bus&gt;s&lt;slot&gt;[f&lt;function&gt;][u&lt;port&gt;][..]1[i&lt;interface&gt;]
*                                         -- USB端口号链
</code></pre><p>新的命名方案的一个小的缺点是接口名称相比传统名称有点难以阅读。例如，你可能会发现像enp0s3名字。再者，你再也无法来控制接口名了。</p><p><img src="https://farm4.staticflickr.com/3854/15294996451_fa731ce12c_z.jpg" alt=""></p><p>如果由于某种原因，你喜欢旧的方式，并希望能够选择任意名称分配给CentOS/ RHEL7的设备，你需要重写默认的可预测的命名规则，定义基于MAC地址udev规则。</p><p><strong>下面是如何在CentOS或RHEL7命名网络接口。</strong></p><p>首先，让我们来禁用该可预测命名规则。对于这一点，你可以在启动时传递“net.ifnames=0”的内核参数。这是通过编辑/etc/default/grub并加入“net.ifnames=0”到GRUB_CMDLINE_LINUX变量来实现的。</p><p><img src="https://farm4.staticflickr.com/3898/15315687725_c82fbef5bc_z.jpg" alt=""></p><p>然后运行这条命令来重新生成GRUB配置并更新内核参数。</p><pre><code>$ sudo grub2-mkconfig -o /boot/grub2/grub.cfg 
</code></pre><p><img src="https://farm4.staticflickr.com/3909/15128981250_72f45633c1_z.jpg" alt=""></p><p>接下来，编辑（或创建）一个udev的网络命名规则文件（/etc/udev/rules.d/70-persistent-net.rules），并添加下面一行。更换成你自己的MAC地址（08:00:27:a9:7a:e1）和接口（sushi）。</p><pre><code> $ sudo vi /etc/udev/rules.d/70-persistent-net.rules 
</code></pre><hr><pre><code>SUBSYSTEM==&quot;net&quot;, ACTION==&quot;add&quot;, DRIVERS==&quot;?*&quot;, ATTR{address}==&quot;08:00:27:a9:7a:e1&quot;, ATTR{type}==&quot;1&quot;, KERNEL==&quot;eth*&quot;, NAME=&quot;sushi&quot;
</code></pre><p>最后，重启电脑并验证新的接口名。</p><p><img src="https://farm4.staticflickr.com/3861/15111594847_14e0c5a00d_z.jpg" alt=""></p><p>请注意，配置重命名后的接口仍然是你的责任。如果网络配置（例如，IPv4设置，防火墙规则）是基于旧名称（变更前）的，则需要更新的网络配置以反映更改的名称。</p><hr>`,19)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),s(o,{href:"http://ask.xmodulo.com/change-network-interface-name-centos7.html"},{default:r(()=>[...t[3]||(t[3]=[e("http://ask.xmodulo.com/change-network-interface-name-centos7.html",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=e("译者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:r(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[8]||(t[8]=e(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原创翻译，",-1)),s(o,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[e("Linux中国",-1)])]),_:1}),t[13]||(t[13]=e(" 荣誉推出",-1))])])}const _=i(d,[["render",m]]);export{T as __pageData,_ as default};
